/* Proposed platform workflow. Animation explains data routing; no training or simulator runs here. */
function platformMini(kind){
 const base='<path d="M6 56H174" stroke="#d9e2e6"/><rect x="133" y="33" width="32" height="23" rx="3" fill="#e7efed" stroke="#a8c2ba"/>';
 if(kind==='human')return `<svg class="pf-mini" viewBox="0 0 180 65" role="img" aria-label="Camera góc nhìn người, tay đưa vật tới đích">${base}<path d="M12 63L51 35L64 40L42 65M100 65L88 43L100 34L143 65" fill="#ede6f5" stroke="currentColor" stroke-width="2"/><rect x="64" y="25" width="18" height="16" rx="3" fill="#d7a04b"/><path d="M83 29Q111 10 142 27" fill="none" stroke="currentColor" stroke-dasharray="3 3"/></svg>`;
 if(kind==='teleop')return `<svg class="pf-mini" viewBox="0 0 180 65" role="img" aria-label="Người điều khiển tay robot, ghi trạng thái và action">${base}<path d="M15 55L24 20L60 12L88 37M80 36V47M95 36V47" fill="none" stroke="currentColor" stroke-width="5" stroke-linejoin="round"/><rect x="80" y="48" width="15" height="9" rx="2" fill="#d7a04b"/><path d="M110 11H169M110 18H153M110 25H160" stroke="#a8c2ba" stroke-width="2"/></svg>`;
 if(kind==='synthetic')return `<svg class="pf-mini" viewBox="0 0 180 65" role="img" aria-label="Cùng mẫu gốc tạo ba điều kiện vị trí khác nhau">${[0,1,2].map(i=>`<g transform="translate(${i*61} 0)"><rect x="1" y="9" width="55" height="45" rx="4" fill="#fbf5e9" stroke="#e5d6ba"/><rect x="${10+i*10}" y="${34-i*5}" width="10" height="9" rx="2" fill="#d7a04b"/><rect x="39" y="33" width="10" height="12" rx="2" fill="#e7efed" stroke="#a8c2ba"/><path d="M15 25Q25 10 43 28" fill="none" stroke="currentColor" stroke-dasharray="2 3"/></g>`).join('')}</svg>`;
 return '';
}
function platformNode(n){const mini=['human','teleop','synthetic'].includes(n.id)?platformMini(n.kind):n.id==='bundle'?'<div class="pf-bundle-stack"><span>Weights đã học</span><span>Processor + train stats</span><span>Robot profile + recipe</span></div>':n.id==='runtime'?platformMini('teleop'):'';return `<button type="button" class="pf-node" data-node="${esc(n.id)}" data-kind="${esc(n.kind)}" style="grid-column:${n.col};grid-row:${n.row}" aria-controls="pf-detail" aria-label="${esc(n.title)}: xem đầu vào, xử lý và nơi sử dụng"><span class="pf-node-label">${esc(n.label)}</span><h3>${esc(n.title)}</h3>${mini}<p>${esc(n.summary)}</p><div class="pf-node-tags">${n.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></button>`;}
function platformSeedScene(id,title,body){return `<div class="pf-seed-scene"><svg viewBox="0 0 190 145" data-pf-scene="${id}" role="img" aria-label="${esc(title)}"><rect x="9" y="9" width="171" height="126" rx="8" fill="#f3f7f8" stroke="#d9e2e6"/><path d="M16 51H172M16 91H172M55 17V127M95 17V127M135 17V127" stroke="#e3eaed"/><rect x="137" y="82" width="30" height="27" rx="3" fill="#e7efed" stroke="#8bae9f"/><path class="pf-seed-trajectory" d="M58 94Q85 38 151 94" fill="none" stroke="#087d7b" stroke-width="2.5" stroke-dasharray="4 3"/><path class="pf-seed-arm" d="M24 28L48 50L58 85" fill="none" stroke="#8196a1" stroke-width="6" stroke-linecap="round"/><rect class="pf-seed-part" x="50" y="86" width="16" height="16" rx="3" fill="#d7a04b"/></svg><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`;}
function platformSyntheticSection(){return `<section class="pf-section" id="pf-synthetic"><header class="pf-section-heading"><div><span class="pf-kicker">01 / SYNTHETIC FACTORY</span><h2>Synthetic được tạo bằng logic nào?</h2></div><p>Từ mẫu gốc, platform tạo thêm điều kiện cần học. Đường tạo quyết định có được giữ nhãn action hay phải tạo nhãn mới.</p></header><div class="pf-methods">
 <article class="pf-method"><small>A / APPEARANCE AUGMENTATION</small><h3>Đổi hình ảnh, giữ đúng nghĩa thao tác</h3><div class="pf-method-steps"><div><b>Mẫu robot có action</b><span>RGB, state, action và calibration gốc.</span></div><div><b>Biến đổi ảnh có kiểm soát</b><span>Ánh sáng, màu hoặc nền khi không làm sai vật/task. Biến đổi camera cần cập nhật geometry tương ứng.</span></div><div><b>Kiểm nhãn còn hợp lệ</b><span>Chỉ giữ action cũ khi hình ảnh mới vẫn tương ứng đúng thao tác đó.</span></div></div><div class="pf-method-result">Dùng ở action training khi nhãn còn đúng</div><p class="pf-method-note">Không đổi vị trí vật trong ảnh rồi giữ nguyên action một cách máy móc.</p></article>
 <article class="pf-method" data-primary="true"><small>B / SIM-EXECUTED TRAJECTORIES</small><h3>Đổi tình huống, thực thi và ghi dữ liệu mới</h3><div class="pf-method-steps"><div><b>1. Seed teleop + scene/robot model</b><span>Phân đoạn gắp, chuyển, đặt theo frame của vật và đích.</span></div><div><b>2. Đổi pose, ghép và nội suy</b><span>Biến đổi đoạn theo vị trí mới trong miền cho phép. Action targets phải đúng controller.</span></div><div><b>3. Execute trong simulator</b><span>Controller chạy thao tác. Ghi RGB, state, actions và phản hồi mới.</span></div><div><b>4. QA physics và outcome</b><span>Kiểm contact/collision, tracking, giữ vật và hoàn thành task. Loại positive mẫu không đạt.</span></div></div><div class="pf-method-result">Dùng ở action training với trajectory mới</div><p class="pf-method-note">Cần simulator và task/controller adapter. Biến đổi hình học chưa đủ để gọi trajectory hợp lệ.</p></article>
 <article class="pf-method"><small>C / NEURAL VIDEO GENERATION</small><h3>Sinh video rồi định tuyến theo nhãn</h3><div class="pf-method-steps"><div><b>Thích nghi video generator</b><span>Học embodiment và chuyển động robot từ dữ liệu phù hợp.</span></div><div><b>Ảnh đầu + lệnh + điều kiện</b><span>Generator sinh video tình huống mới. Kiểm task, chuyển động và chất lượng.</span></div><div><b>RGB-only hoặc pseudo-actions</b><span>RGB-only dùng video objective. IDM/latent-action labeler là tuyến thêm, cần validation riêng.</span></div></div><div class="pf-method-result">Video objective; action training có điều kiện</div><p class="pf-method-note">Pseudo-actions là nhãn ước lượng, khác action ghi từ robot/simulator. Generator làm việc offline.</p></article>
 </div><div class="pf-seed-lab"><div><span class="pf-kicker">MẪU GỐC → VARIANT → EXECUTION</span><h3>Cùng thao tác, vị trí vật mới</h3><p>Chọn vị trí để thấy quỹ đạo đề xuất thay đổi theo vật. Simulator phải chạy và kiểm lại trước khi phát hành dữ liệu.</p><div class="pf-position-options" role="group" aria-label="Chọn vị trí vật cho biến thể"><button type="button" data-pf-position="left" aria-pressed="false">Lệch trái</button><button type="button" data-pf-position="center" aria-pressed="true">Ở giữa</button><button type="button" data-pf-position="right" aria-pressed="false">Lệch phải</button></div><p>Hình giải thích phép biến đổi, chưa phải output simulator.</p></div><div class="pf-seed-scenes">${platformSeedScene('original','Seed đã có','Một mẫu robot hợp lệ trong train.')}${platformSeedScene('variant','Quỹ đạo đề xuất','Retarget theo pose vật/đích, nối các đoạn.')}${platformSeedScene('executed','Execute + kiểm lại','Chỉ phát hành khi action/physics/outcome đạt.')}</div></div></section>`;}
function platformTrainingSection(){return `<section class="pf-section" id="pf-training"><header class="pf-section-heading"><div><span class="pf-kicker">02 / MODEL ENGINE CORE</span><h2>Cùng một platform, các tín hiệu học đi vào đâu?</h2></div><p>Kế thừa pretrained policy. Ví dụ dưới dùng future alignment kiểu FLARE để giải thích nhánh human RGB-only; nhánh này cần được tích hợp vào engine.</p></header><div class="pf-train-layout"><div class="pf-train-diagram"><div class="pf-batch-tabs" role="group" aria-label="Chọn training batch"><button type="button" data-pf-batch="human" aria-pressed="true">Human RGB-only</button><button type="button" data-pf-batch="teleop" aria-pressed="false">Robot teleop</button><button type="button" data-pf-batch="sim" aria-pressed="false">Sim trajectory</button><button type="button" data-pf-batch="generated" aria-pressed="false">Generated video</button></div><div class="pf-train-rows">
 <div class="pf-train-row"><div class="pf-train-block"><strong>Ảnh hiện tại + lệnh</strong><small>Conditioning, không đọc đáp án tương lai</small></div><span aria-hidden="true">→</span><div class="pf-train-block"><strong>VLM / Eagle</strong><small>Features ảnh và ngôn ngữ</small></div><span aria-hidden="true">→</span><div class="pf-train-block"><strong>DiT / Action Expert</strong><small>Action tokens + future tokens của recipe</small></div></div>
 <div class="pf-train-row" data-objective="future"><div class="pf-train-block"><strong>Frames ở bước sau</strong><small>Đáp án offline cùng episode</small></div><span aria-hidden="true">→</span><div class="pf-train-block"><strong>Target encoder frozen</strong><small>Tạo future feature targets</small></div><span aria-hidden="true">↔</span><div class="pf-train-block"><strong>Future alignment loss</strong><small>So future tokens dự đoán với targets</small></div></div>
 <div class="pf-train-row" data-objective="action" data-disabled="true"><div class="pf-train-block"><strong>State + future actions</strong><small>Actions + noise/time theo flow recipe</small></div><span aria-hidden="true">→</span><div class="pf-train-block"><strong>Action Expert dự đoán</strong><small>Flow velocity của action sequence</small></div><span aria-hidden="true">↔</span><div class="pf-train-block"><strong>Action flow loss</strong><small>So velocity với action − noise</small></div></div>
 </div><div class="pf-loss-footer" id="pf-loss-caption" aria-live="polite"></div></div><div class="pf-training-copy" id="pf-batch-detail" aria-live="polite"></div></div><details class="pf-motion"><summary>Nếu human ego có tracking bàn tay/cổ tay thì học thêm thế nào?</summary><p><strong>Đây là một extension khác.</strong> Human tracked wrist poses + calibration/time/masks và robot measured wrist poses từ forward kinematics tạo common-motion targets. Human adapter/common head và shared motor trunk học motion objective; native robot head vẫn học robot-action labels. Wrist poses của người không đổi tên thành robot joint actions, và wrist-only không tự có finger/contact labels.</p><p>Cần implement common route, kiểm gradients và so cùng architecture có/không human supervision. Không mặc định dùng đồng thời motion extension, FLARE và FOCA rồi quy toàn bộ gain cho human data. <a href="#learning">Xem blueprint model và training routes →</a></p></details><p class="pf-target-note">Minh họa FLARE-style ưu tiên frozen VLM như official GR00T N1.5. Selected FluxVLA recipe có thể mở visual modules; trainability phải ghi bằng manifest và gradient checks. FOCA là candidate riêng, không được coi là cùng một loss.</p></section>`;}
function platformRuntimeSection(){return `<section class="pf-section" id="pf-runtime"><header class="pf-section-heading"><div><span class="pf-kicker">03 / ONLINE INFERENCE</span><h2>Dữ liệu đã học được sử dụng khi robot chạy như thế nào?</h2></div><p>Kinh nghiệm nằm trong weights và cấu hình đã học. Mỗi lượt điều khiển lấy quan sát mới từ robot.</p></header><div class="pf-runtime-flow">${[
 ['Input hiện tại','RGB + text + state','Camera nhìn cảnh, lệnh nêu task và sensors trả trạng thái robot.'],
 ['Hiểu quan sát','VLM / Eagle','Mã hóa ảnh và lệnh thành features.'],
 ['Chọn động tác','Action Expert','Features + state tạo action chunks theo config.'],
 ['Thực thi','Binding + controller','Đổi units/order/rate đúng profile rồi gửi commands.'],
 ['Phản hồi','Readback + outcome','Ghi chuyển động thực, lỗi, can thiệp, độ trễ và usage.']
 ].map(([a,b,c])=>`<article><small>${esc(a)}</small><h3>${esc(b)}</h3><p>${esc(c)}</p></article>`).join('')}</div><div class="pf-final">Human video, seed teleop và synthetic generator phục vụ chuẩn bị/training offline. Future target frames là đáp án training. Lúc inference, policy dùng context hiện tại và history theo config; không nhận video tương lai thật.</div></section>`;}
function platformFeedbackSection(){return `<section class="pf-section" id="pf-feedback"><header class="pf-section-heading"><div><span class="pf-kicker">04 / DATA FLYWHEEL</span><h2>Kết quả chạy quyết định dữ liệu cho vòng học tiếp theo</h2></div><p>Kỹ sư xét bằng chứng, chọn can thiệp và budget. Thu thêm dữ liệu là một lựa chọn trong vòng này.</p></header><div class="pf-cases">
 <article class="pf-case"><h3>Command khác chuyển động thực</h3><p><b>Kiểm:</b> mapping, units, timing và controller/readback.</p><p><b>Xử lý:</b> sửa integration, khóa cấu hình và lập lại baseline.</p><strong>Quay lại runtime trước khi kết luận cần data mới</strong></article>
 <article class="pf-case"><h3>Thiếu kinh nghiệm ở một tư thế gắp</h3><p><b>Kiểm:</b> hệ thống đúng, expert làm được, train coverage chưa đủ.</p><p><b>Xử lý:</b> thu correction đúng robot hoặc retarget seed và sim-execute khi fidelity phù hợp.</p><strong>QA → release mới → action training + replay</strong></article>
 <article class="pf-case"><h3>Yếu ở diễn biến hoặc điều kiện nhìn mới</h3><p><b>Kiểm:</b> input/representation và các giả thuyết khác bằng phép thử có kiểm soát.</p><p><b>Xử lý:</b> reuse/augment phù hợp; xem xét human/generated video hay motion labels nếu đúng supervision cần học.</p><strong>Nhánh được chọn phải có đối chứng và cost receipts</strong></article>
 </div><div class="pf-final"><b>Mỗi vòng giữ liên kết:</b> lỗi → giả thuyết → quyết định → source/parent → dataset release → train run → checkpoint → robot outcome → tổng công. So cùng quality/coverage, giữ no-gain và regression. Freeze rồi independent final ngoài vòng tuning. Task tiếp theo đo được phần dùng lại thay vì mặc định mọi robot dùng chung action profile.</div></section>`;}
function renderPlatformWorkflow(){const d=PLATFORM_WORKFLOW;return `<div class="platform-page" id="platform-workflow"><header class="pf-hero"><div><span class="pf-kicker">HUMANOID SKILL LEARNING / PLATFORM WORKFLOW</span><h1>Từ trải nghiệm người và robot<br>đến <em>kỹ năng có thể cải thiện.</em></h1><p>Human ego video, teleop và synthetic đi qua Data Core, học theo tín hiệu thực có, tạo model chạy robot. Kết quả quay về để chọn dữ liệu cho vòng tiếp theo.</p></div><button type="button" class="pf-present" data-pf-present aria-pressed="false">Trình chiếu workflow ↗</button></header>
 <div class="pf-toolbar"><div class="pf-sources" role="group" aria-label="Theo dõi nguồn dữ liệu">${d.sources.map(s=>`<button type="button" class="pf-source" data-pf-source="${esc(s.id)}" aria-pressed="${s.id==='all'}">${esc(s.label)}</button>`).join('')}</div><button type="button" class="pf-play" data-pf-play>▶ Chạy workflow</button></div>
 <div class="pf-graph-shell"><div class="pf-boundaries"><span>OFFLINE / DỮ LIỆU → TRAINING → MODEL</span><span>ONLINE / ROBOT</span></div><div class="pf-map"><svg class="pf-edges" aria-hidden="true"></svg>${d.nodes.map(platformNode).join('')}</div><div class="pf-return-head"><strong>DATA FLYWHEEL / KẾT QUẢ QUAY VỀ DATA CORE</strong><span>Kỹ sư duyệt quyết định • Final độc lập nằm ngoài vòng này</span></div><div class="pf-feedback">${d.feedback.map((f,i)=>`<article data-pf-feedback="${i}"><strong>${esc(f.title)}</strong><p>${esc(f.body)}</p></article>`).join('')}</div><div class="pf-loop-rail"><span></span></div><div class="pf-loop-label">Release mới + mẫu cũ → học lại → chạy và so kết quả</div></div>
 <div class="pf-stage-nav" role="group" aria-label="Các giai đoạn platform">${d.phases.map((p,i)=>`<button type="button" data-pf-phase="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${esc(p.label)}</button>`).join('')}</div><div class="pf-detail" id="pf-detail" aria-live="polite"></div><p class="pf-scope">Sơ đồ thiết kế platform. Animation giải thích luồng dữ liệu, không chạy training/simulator. Native multi-source training, human transfer và lợi ích tiết kiệm của đội chưa được đo. PoC robot-data-first và nhánh mở rộng có trạng thái riêng.</p>
 ${platformSyntheticSection()}${platformTrainingSection()}${platformRuntimeSection()}${platformFeedbackSection()}
 <div class="pf-references">${d.references.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a>`).join('')}</div><div class="pf-page-links"><a href="#overview">Bài toán, hiệu quả và kế hoạch →</a><a href="#engine">Model Engine Core chi tiết →</a><a href="#architecture">Data Core và contracts →</a></div></div>`;}
function initPlatformWorkflow(signal){
 const root=document.querySelector('#platform-workflow');if(!root)return;
 const d=PLATFORM_WORKFLOW,q=s=>root.querySelector(s),qa=s=>Array.from(root.querySelectorAll(s));
 const colors={human:'#7658a8',teleop:'#087d7b',synthetic:'#ab701e',shared:'#3a546b'};
 let source='all',phase=0,selectedNode=null,playing=false,frame=0,start=0,elapsed=0,paths=[],generationFrame=0;
 const duration=5200,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function eligible(n){return source==='all'||n.kind===source||['shared','runtime'].includes(n.kind)||(source==='synthetic'&&['action-train','video-train','teleop'].includes(n.id));}
 function stop(){playing=false;cancelAnimationFrame(frame);frame=0;q('[data-pf-play]').textContent='▶ Chạy workflow';}
 function detailNode(id){const n=d.nodes.find(n=>n.id===id);if(!n)return;selectedNode=id;stop();q('#pf-detail').innerHTML=`<div class="pf-detail-top"><div><small>${esc(n.label)}</small><h3>${esc(n.title)}</h3></div><div class="pf-step-controls"><button type="button" data-pf-overview>Trở về giai đoạn</button></div></div><div class="pf-detail-grid">${[['ĐẦU VÀO',n.input],['XỬ LÝ',n.process],['ĐẦU RA',n.output],['DÙNG Ở ĐÂU',n.use]].map(([t,b])=>`<div><strong>${t}</strong><p>${esc(b)}</p></div>`).join('')}</div><div class="pf-detail-state">${esc(n.state)}</div>`;highlight();}
 function detailPhase(){const p=d.phases[phase];q('#pf-detail').innerHTML=`<div class="pf-detail-top"><div><small>0${phase+1} / ${esc(p.label.toUpperCase())}</small><h3>${esc(p.title)}</h3></div><div class="pf-step-controls"><button type="button" data-pf-back ${phase===0?'disabled':''}>← Trước</button><button type="button" data-pf-next ${phase===6?'disabled':''}>Tiếp →</button></div></div><p class="pf-phase-body">${esc(p.body)}</p><div class="pf-phase-output"><b>Đầu ra:</b> ${esc(p.output)}</div>`;}
 function highlight(){
   qa('[data-pf-source]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pfSource===source)));
   qa('[data-pf-phase]').forEach(b=>b.setAttribute('aria-pressed',String(!selectedNode&&Number(b.dataset.pfPhase)===phase)));
   qa('[data-node]').forEach(el=>{const n=d.nodes.find(n=>n.id===el.dataset.node);el.dataset.dimmed=String(!eligible(n));el.dataset.active=String(selectedNode?selectedNode===n.id:d.phases[phase].nodes.includes(n.id)&&eligible(n));});
   qa('[data-pf-feedback]').forEach(el=>el.dataset.active=String(!selectedNode&&phase>=5&&(phase===5?Number(el.dataset.pfFeedback)<3:Number(el.dataset.pfFeedback)>=3)));
   paths.forEach(({edge,path,dot})=>{const active=source==='all'||edge.source===source||edge.source==='shared';path.style.opacity=active?'.62':'.1';path.style.strokeWidth=active?'1.6':'1';dot.style.opacity=0;});
 }
 function drawEdges(){
   const map=q('.pf-map'),svg=q('.pf-edges'),box=map.getBoundingClientRect();
   svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);svg.innerHTML=`<defs>${Object.entries(colors).map(([k,c])=>`<marker id="pf-arrow-${k}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${c}"/></marker>`).join('')}</defs>`;paths=[];
   const ns='http://www.w3.org/2000/svg';
   d.edges.forEach(edge=>{
     const a=q(`[data-node="${edge.from}"]`).getBoundingClientRect(),b=q(`[data-node="${edge.to}"]`).getBoundingClientRect();
     let ax=a.right-box.left,ay=a.top+a.height*.5-box.top,bx=b.left-box.left,by=b.top+b.height*.5-box.top,pathD;
     if(edge.kind==='seed'){ax=a.left+a.width*.5-box.left;ay=a.bottom-box.top;bx=b.left+b.width*.5-box.left;by=b.top-box.top;pathD=`M${ax} ${ay}L${bx} ${by}`;}
     else if(b.left<a.left+5){ax=a.left+a.width*.7-box.left;ay=a.bottom-box.top;bx=b.left+b.width*.3-box.left;by=b.top-box.top;const mid=(ay+by)/2;pathD=`M${ax} ${ay}C${ax} ${mid} ${bx} ${mid} ${bx} ${by}`;}
     else{const gap=Math.max(8,(bx-ax)/2);if(edge.kind==='video'){ay=a.top+20-box.top;by=b.bottom-20-box.top;}pathD=`M${ax} ${ay}C${ax+gap} ${ay} ${bx-gap} ${by} ${bx} ${by}`;}
     const path=document.createElementNS(ns,'path');path.setAttribute('d',pathD);path.setAttribute('fill','none');path.setAttribute('stroke',colors[edge.source]);path.setAttribute('marker-end',`url(#pf-arrow-${edge.source})`);if(['video','seed'].includes(edge.kind))path.setAttribute('stroke-dasharray','3 4');svg.append(path);
     const dot=document.createElementNS(ns,'circle');dot.setAttribute('r','3.7');dot.setAttribute('fill',colors[edge.source]);dot.style.opacity=0;svg.append(dot);paths.push({edge,path,dot});
   });highlight();
 }
 function selectPhase(i,keepPlaying=false){if(!keepPlaying)stop();selectedNode=null;phase=Math.max(0,Math.min(6,i));elapsed=0;start=performance.now();detailPhase();highlight();}
 function tick(now){
   if(!playing)return;elapsed=now-start;const t=Math.min(elapsed/duration,1);
   if(!reduced)paths.forEach(({edge,path,dot})=>{const active=(source==='all'||edge.source===source||edge.source==='shared')&&edge.phase===phase;dot.style.opacity=active&&t>.07&&t<.94?1:0;if(active){const p=path.getPointAtLength(path.getTotalLength()*t);dot.setAttribute('cx',p.x);dot.setAttribute('cy',p.y);}});
   const back=q('.pf-loop-rail span');back.style.opacity=!reduced&&phase>=5&&t>.05&&t<.95?1:0;back.style.left=`${(1-t)*98}%`;
   if(t>=1){if(phase===6){stop();back.style.opacity=0;return;}selectPhase(phase+1,true);}
   frame=requestAnimationFrame(tick);
 }
 const batches={
  human:{title:'Human RGB-only học future features',body:'Current frames/text tạo conditioning. Future frames qua target encoder thành đáp án. Human batch chỉ dùng future alignment; không có robot-action loss.',action:false,loss:'Human batch: L_future. Robot batch trong co-training: L_action + λ L_future.',modules:[['VLM / Eagle','Frozen trong minh họa này'],['Future tokens / DiT modules','Cập nhật theo FLARE-style recipe'],['Native action labels','Chưa có ở human RGB-only']],note:'Cần triển khai loader/loss và kiểm gradients. Robot-action adaptation vẫn là nhánh riêng trong thiết kế platform.'},
  teleop:{title:'Teleop dạy hành động đúng của robot',body:'RGB/text/state hiện tại là điều kiện. Future actions từ demonstration làm targets cho flow loss. Khi recipe hỗ trợ FLARE, future frames của robot cũng cung cấp alignment targets.',action:true,loss:'Robot batch: L_action + λ L_future khi future branch thực sự được tích hợp.',modules:[['VLM / Eagle','Freeze/tune theo manifest'],['Action Expert / adapters','Cập nhật từ native actions'],['Future tokens / modules','Cập nhật nếu recipe có nhánh future']],note:'Flow target minh họa theo convention actions − noise. Tần số, horizon, normalization và masks lấy config đã pin.'},
  sim:{title:'Trajectory mô phỏng đi cùng nhánh action',body:'Simulator execution tạo RGB/state/actions mới theo robot profile. Sau QA, loader dùng cùng robot-action view như teleop, giữ provenance và trộn với mẫu gốc để kiểm regression.',action:true,loss:'S_exec batch: robot-action loss; thêm future loss chỉ ở recipe hỗ trợ.',modules:[['Robot action view','Cùng semantics với target profile'],['Action Expert / adapters','Cập nhật theo cùng recipe đối chứng'],['Replay mẫu cũ','Giữ coverage đã làm tốt']],note:'Mẫu sim chưa chứng minh chuyển sang robot thật. Variants không tăng số roots độc lập; failed actions không là positive demonstrations.'},
  generated:{title:'Video sinh chưa tự có action labels',body:'Generated RGB-only có task/time và future frames đã kiểm. Tuyến này dùng video future objective. Nếu thêm IDM để gán pseudo-actions, phải phát hành view và QA riêng trước khi cân nhắc action training.',action:false,loss:'Generated RGB-only batch: L_future. Không tự bật L_action.',modules:[['Video generator','Offline, tách khỏi policy'],['Future tokens / policy modules','Học alignment theo recipe'],['IDM pseudo-actions','Optional, cần kiểm riêng']],note:'Pipeline DreamGen gốc có bước labeler. Video-only future route ở đây là một lựa chọn platform, không gọi là tái lập toàn DreamGen.'}
 };
 function setBatch(id){const b=batches[id];if(!b)return;qa('[data-pf-batch]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.pfBatch===id)));q('[data-objective="action"]').dataset.disabled=String(!b.action);q('#pf-loss-caption').textContent=b.loss;q('#pf-batch-detail').innerHTML=`<h3>${esc(b.title)}</h3><p>${esc(b.body)}</p>${b.modules.map(([a,c])=>`<div class="pf-module-row"><strong>${esc(a)}</strong><span>${esc(c)}</span></div>`).join('')}<div class="pf-target-note">${esc(b.note)}</div>`;}
 function setPosition(id){
   const positions={left:[48,72],center:[88,72],right:[112,105]},target=positions[id];if(!target)return;cancelAnimationFrame(generationFrame);
   qa('[data-pf-position]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pfPosition===id)));
   const original=q('[data-pf-scene="original"]'),variant=q('[data-pf-scene="variant"]'),executed=q('[data-pf-scene="executed"]');
   function update(svg,x,y,motion){svg.querySelector('.pf-seed-part').setAttribute('x',x-8);svg.querySelector('.pf-seed-part').setAttribute('y',y-8);svg.querySelector('.pf-seed-trajectory').setAttribute('d',`M${target[0]} ${target[1]}Q111 25 151 95`);svg.querySelector('.pf-seed-arm').setAttribute('d',`M24 28L${24+(x-24)*.55} ${Math.max(31,y-40)}L${x} ${y-9}`);svg.querySelector('.pf-seed-trajectory').style.strokeDasharray=motion?'none':'4 3';}
   original.querySelector('.pf-seed-trajectory').setAttribute('d','M58 94Q85 38 151 94');update(variant,target[0],target[1],false);
   const origin=performance.now(),span=1500;
   function motion(now){const t=reduced?1:Math.min((now-origin)/span,1),u=t*t*(3-2*t);const x=target[0]+(151-target[0])*u,y=(1-u)*(1-u)*target[1]+2*(1-u)*u*25+u*u*95;update(executed,x,y,true);if(t<1)generationFrame=requestAnimationFrame(motion);}
   motion(origin);
 }
 function presentation(on){document.body.classList.toggle('platform-presenting',on);const b=q('[data-pf-present]');b.setAttribute('aria-pressed',String(on));b.textContent=on?'Quitter la présentation / Esc':'Trình chiếu workflow ↗';if(on)b.textContent='Thoát trình chiếu / Esc';requestAnimationFrame(drawEdges);}
 root.addEventListener('click',e=>{
   const b=e.target.closest('button');if(!b||!root.contains(b))return;
   if(b.dataset.pfSource){source=b.dataset.pfSource;selectPhase(0);}
   if(b.dataset.node)detailNode(b.dataset.node);
   if(b.dataset.pfPhase!==undefined)selectPhase(Number(b.dataset.pfPhase));
   if(b.hasAttribute('data-pf-overview')){selectedNode=null;detailPhase();highlight();}
   if(b.hasAttribute('data-pf-back'))selectPhase(phase-1);
   if(b.hasAttribute('data-pf-next'))selectPhase(phase+1);
   if(b.hasAttribute('data-pf-play')){if(playing){stop();}else{selectPhase(0);playing=true;start=performance.now();q('[data-pf-play]').textContent='Ⅱ Tạm dừng';frame=requestAnimationFrame(tick);}}
   if(b.dataset.pfBatch)setBatch(b.dataset.pfBatch);
   if(b.dataset.pfPosition)setPosition(b.dataset.pfPosition);
   if(b.hasAttribute('data-pf-present'))presentation(!document.body.classList.contains('platform-presenting'));
 },{signal});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('platform-presenting'))presentation(false);},{signal});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();cancelAnimationFrame(generationFrame);}},{signal});
 const observer=new ResizeObserver(()=>drawEdges());observer.observe(q('.pf-map'));
 signal.addEventListener('abort',()=>{stop();cancelAnimationFrame(generationFrame);observer.disconnect();document.body.classList.remove('platform-presenting');},{once:true});
 detailPhase();setBatch('human');setPosition('center');requestAnimationFrame(drawEdges);
}
